<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\ValueObject\Accessor\TenantLoginProviderSamlIdpEntityIdAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSamlIdpEntityIdAccessor trait.
 *
 * Covers null default, string/VO assignment via withSamlIdpEntityId,
 * getSamlIdpEntityId/samlIdpEntityId accessors, and isSamlIdpEntityIdChanged with/without original.
 */
class TenantLoginProviderSamlIdpEntityIdAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSamlIdpEntityId creates a new instance with the SamlIdpEntityId set
     * from a string value, and getSamlIdpEntityId returns the primitive string.
     */
    public function testWithSamlIdpEntityIdFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpEntityIdAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpEntityId('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getSamlIdpEntityId());
    }
    /**
     * Asserts that withsamlIdpEntityId has access to the value object
     * from a string value, and getSamlIdpEntityId returns the primitive string.
     */
    public function testWithSamlIdpEntityIdFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpEntityIdAccessorUnitTest();

        // Act
        $result = $holder->withSamlIdpEntityId('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->samlIdpEntityId()->value());
    }
    public function testChangedSamlIdpEntityId(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSamlIdpEntityIdAccessorUnitTest();
        $original = $holder->withSamlIdpEntityId('one');
        $same = $holder->withSamlIdpEntityId('one');
        $modified = $holder->withSamlIdpEntityId('other');

        // Act
        $unchanged = $holder->isSamlIdpEntityIdChanged();
        $withSame = $original->isSamlIdpEntityIdChanged($same);
        $withDiferent = $original->isSamlIdpEntityIdChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantLoginProviderSamlIdpEntityIdAccessorUnitTest
{
    use TenantLoginProviderSamlIdpEntityIdAccessor;
}
